import pandas as pd
import numpy as np

trips = tables['trips']

# Filter to Season 6 only
s6_trips = trips[trips['fished_date_season'] == 6].copy()

# Group by class and DOY window
# Create DOY ranges: early peak (14-60), spring tail (85-120), fall (250+)
def classify_window(doy):
    if 14 <= doy <= 60:
        return 'early_peak'
    elif 85 <= doy <= 120:
        return 'spring_tail'
    elif 250 <= doy <= 305:
        return 'fall'
    else:
        return 'other'

s6_trips['window'] = s6_trips['fished_date_doy'].apply(classify_window)

# Calculate per-trip stats
trip_stats = s6_trips.groupby(['fished_date_doy', 'cls']).agg({
    'yt': 'sum',
    'anglers': 'sum'
}).reset_index()

trip_stats['yt_per_angler'] = trip_stats['yt'] / trip_stats['anglers']
trip_stats['trip_count'] = s6_trips.groupby(['fished_date_doy', 'cls']).size().values

# Window analysis
window_stats = s6_trips.groupby(['window', 'cls']).agg({
    'yt': 'sum',
    'anglers': 'sum'
}).reset_index()

window_stats['yt_per_angler'] = window_stats['yt'] / window_stats['anglers']
window_stats = window_stats.sort_values(['window', 'yt_per_angler'], ascending=[True, False])

print("=== S6 SEASONAL PATTERNS BY WINDOW AND CLASS ===\n")
for window in ['early_peak', 'spring_tail', 'fall', 'other']:
    w_data = window_stats[window_stats['window'] == window]
    if len(w_data) > 0:
        print(f"\n{window.upper()} (DOY ranges):")
        for idx, row in w_data.iterrows():
            print(f"  {row['cls']:15s}: {row['yt_per_angler']:6.3f} yt/angler ({row['yt']:.0f} YT, {row['anglers']:.0f} anglers)")

